//RC pass and change
//History:
//original:https://www.shadertoy.com/view/X33BzN
//fork1 : https://www.shadertoy.com/view/XXdBWl
//fork2 : https://www.shadertoy.com/view/lXGBWR
//fork3 (this sketch) : https://www.shadertoy.com/view/XXGfDy
float TAU = 6.28318;

// Cycle through a color palette with a cosine wave
vec3 palette( float t ) {
    vec3 offset = vec3(0.3, 0.4, 0.2);
    vec3 amplitude = vec3(0.1, 0.1, 0.2);
    vec3 frequency = vec3(1.0, 1.0, 1.0);
    vec3 phase = vec3(0.263, 0.416, 0.557);

    return offset + amplitude * cos(TAU * (frequency * t + phase));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
     // Normalized pixel coordinates (from -1 to 1)
    // (-1,-1) = bottom left corner
    // (1,1) = top right corner
    vec2 uv = fragCoord / iResolution.xy * 2.0 - 1.0;
    vec3 baseColor = palette(0.1 * iTime);

    // Get center point of viewprt
    vec2 center = iResolution.xy * 0.5;

    // Take a temporary reading of the current UV coordinates so that we can reset them later
    vec2 originalUV = uv; 

    // This code basically makes rly tiny ringlets using sine + distance fn
    // which look like noise when made rly small 
    // (decreasing this number makes it more obvious)
    // and scaling the UV space
    // then we yolo'd, no way i know what everything does :) 
    float howSmallAreTheLittleRings = 40000000.0;
    float ringletSpeed = iTime * .3;
    // replacing sin with tan or cos is also pleasing
    uv *= howSmallAreTheLittleRings * tan(
            distance(uv, vec2(0.,0.)) + (ringletSpeed)
        ); 
    // making the color strength in the range of 0 --> 1
    // makes it look more white noisy
    // bigger values are smoover
    float colorStrength = 4.0;
    vec3 textureColor = baseColor + (sin(uv.y) / colorStrength);

    // reset the UV so we're not in a crazy dimension
    uv = originalUV;

    //lava circle thing:
    //compute distance from center (0, 0)
    float distFromCenter = length(uv)*abs(cos(iTime*0.1+uv.x*uv.y));

    //radius for annulus
    float radius =  0.4  + 0.1 * sin(iTime*0.3);  
    float radius2 = 0.1 + 0.1 * sin(iTime*0.3); 
    vec3 tmpColor = vec3(0.);    

    //if the fragment is within threshold(radius and radius2) bounds - invert the color
    if (distFromCenter < radius && distFromCenter > radius2) {
        //texture the cool sine-y ring by adding our color from above
        textureColor += baseColor;
    }

    vec3 color = textureColor;

    // Calculate sequentially smaller rectangles based on viewport
    float rectCreationInterval = iTime / 2.0; // Should be every 2 seconds
    float rectDiminish = 0.85; // The size difference between rects
    float minSize = 20.0; // Where to stop making smaller rects
    float rectWidth = iResolution.x;
    float rectHeight = iResolution.y;
    // Use an integer here to constrain the loop that will reset when the rects stop scaling
    int rectangleCount = int(mod(floor(iTime / 2.0), 18.0));

    // the loop to create rectangles
    for (int i=0; i<=rectangleCount; i++) {
        vec3 inverseColor = vec3(1.0) - textureColor;
        // create the rectangles based on the center point
        vec2 middleRect = vec2(rectWidth, rectHeight) * 0.5;
        vec2 rectLeft = center - middleRect;
        vec2 rectRight = center + middleRect;

        // if the shader is in the right place, color it
        if (fragCoord.x > rectLeft.x && fragCoord.x < rectRight.x &&
            fragCoord.y > rectLeft.y && fragCoord.y < rectRight.y) {
            // invert the colors alternately
            color = (i % 2 == 0) ? textureColor : inverseColor;
        }

        // reduce size of the following rect
        rectWidth *= rectDiminish;
        rectHeight *= rectDiminish;

        // stop infinite rectangles
        if (rectWidth < minSize || rectHeight < minSize) {
            break;
        }

    }
    // Output with an alpha of 1
    fragColor = vec4(color, 1);
}
